"""Selective header-compression engine (protocol v1.1).

Reads one JSON request per stdin line, writes one JSON response per line.
Two modes: 'replay' (control/data-plane audit) and 'plan' (offline admission).
Standard library only.
"""
import sys
import json
import re
from bisect import bisect_left
from operator import itemgetter

MAX_LINE = 16 * 1024 * 1024
MAX_PKT_BYTES = 2 * 1024 * 1024
MAX_OFFER_HDR_BYTES = 65536
MEMO_CAP = 3 << 19

_ID = re.compile(r'[A-Za-z0-9_.-]{1,32}')
_HEX = re.compile(r'[0-9a-f]*')
_KIND = re.compile(r'[KDZQT]*')

REPLAY_FLOW_KEYS = frozenset(('id', 'path', 'template', 'kinds', 'labels'))
PLAN_FLOW_KEYS = frozenset(('id', 'path', 'template', 'kinds'))
REPLAY_KEYS = frozenset(('mode', 'capacities', 'flows', 'events'))
PLAN_KEYS = frozenset(('mode', 'capacities', 'flows', 'warmup', 'pinned', 'offers'))
PUT_KEYS = frozenset(('op', 'flow', 'node'))
FLOW_KEYS = frozenset(('op', 'flow'))
RESET_KEYS = frozenset(('op',))
PACKET_KEYS = frozenset(('op', 'flow', 'header', 'payload'))
RUN_KEYS = frozenset(('header', 'count'))

FULL8 = (1 << 64) - 1


class Bad(Exception):
    __slots__ = ()


ERR = b'{"error":"input"}\n'
OK = {'status': 'ok'}


def _rej(x):
    raise Bad()


def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad()
        d[k] = v
    return d


def vint(v, lo, hi):
    if type(v) is not int:
        raise Bad()
    if v < lo or v > hi:
        raise Bad()
    return v


def vid(v):
    if type(v) is not str or _ID.fullmatch(v) is None:
        raise Bad()
    return v


def vhex(s, mn, mx):
    if type(s) is not str:
        raise Bad()
    n = len(s)
    if n & 1:
        raise Bad()
    if n > 2 * mx:
        raise Bad()
    if _HEX.fullmatch(s) is None:
        raise Bad()
    b = bytes.fromhex(s)
    if len(b) < mn:
        raise Bad()
    return b


class Flow(object):
    __slots__ = ('id', 'path', 'pathidx', 'N', 'keys', 'labels', 'H', 'tmpl', 'kinds',
                 'dcount', 'qpos', 'tpos', 'kget', 'kexp', 'dmode', 'dget', 'dpos0',
                 'labsh', 'zmask', 'tclear', 'tshift', 'tpos2', 'save', 'knodes')


def parse_caps(c):
    if type(c) is not dict:
        raise Bad()
    if not (1 <= len(c) <= 64):
        raise Bad()
    for k, v in c.items():
        vid(k)
        vint(v, 0, 512)
    return c


def parse_flows(raw, caps, replay):
    if type(raw) is not list:
        raise Bad()
    if len(raw) > (512 if replay else 22):
        raise Bad()
    flows = []
    seen = set()
    want = REPLAY_FLOW_KEYS if replay else PLAN_FLOW_KEYS
    for item in raw:
        if type(item) is not dict:
            raise Bad()
        if frozenset(item) != want:
            raise Bad()
        f = Flow()
        f.id = vid(item['id'])
        if f.id in seen:
            raise Bad()
        seen.add(f.id)
        path = item['path']
        if type(path) is not list or not (2 <= len(path) <= 9):
            raise Bad()
        pset = set()
        for nd in path:
            vid(nd)
            if nd not in caps or nd in pset:
                raise Bad()
            pset.add(nd)
        f.path = tuple(path)
        f.N = len(path)
        f.pathidx = {nd: i for i, nd in enumerate(f.path)}
        tmpl = vhex(item['template'], 8, 256)
        f.tmpl = tmpl
        f.H = H = len(tmpl)
        kinds = item['kinds']
        if type(kinds) is not str or len(kinds) != H:
            raise Bad()
        if _KIND.fullmatch(kinds) is None:
            raise Bad()
        f.kinds = kinds
        if kinds.count('Q') != 1 or kinds.count('T') != 1:
            raise Bad()
        if kinds.count('K') < 1:
            raise Bad()
        f.dcount = dc = kinds.count('D')
        if 4 + dc >= H:
            raise Bad()
        f.qpos = kinds.index('Q')
        f.tpos = kinds.index('T')
        kpos = [i for i, ch in enumerate(kinds) if ch == 'K']
        dpos = [i for i, ch in enumerate(kinds) if ch == 'D']
        zpos = [i for i, ch in enumerate(kinds) if ch == 'Z']
        kp = kpos if len(kpos) != 1 else kpos + kpos
        f.kget = itemgetter(*kp)
        f.kexp = tuple(tmpl[i] for i in kp)
        if not dpos:
            f.dmode = 0
            f.dget = None
            f.dpos0 = -1
        elif len(dpos) == 1:
            f.dmode = 1
            f.dget = None
            f.dpos0 = dpos[0]
        else:
            f.dmode = 2
            f.dget = itemgetter(*dpos)
            f.dpos0 = -1
        full = (1 << (8 * H)) - 1
        zbits = 0
        for p in zpos:
            zbits |= 0xFF << (8 * (H - 1 - p))
        f.zmask = full ^ zbits
        f.tshift = 8 * (H - 1 - f.tpos)
        f.tclear = full ^ (0xFF << f.tshift)
        f.tpos2 = 2 * f.tpos
        f.save = (H - 4 - dc) * f.N
        if replay:
            lb = item['labels']
            if type(lb) is not list or len(lb) != f.N:
                raise Bad()
            f.labels = tuple(vint(x, 16, 1048575) for x in lb)
            f.labsh = tuple(x << 12 for x in f.labels)
            f.keys = tuple((f.path[i], f.labels[i]) for i in range(f.N))
        else:
            f.labels = None
            f.labsh = None
            f.keys = None
        flows.append(f)
    return flows


def parse_events(raw, flows, fmap):
    if type(raw) is not list:
        raise Bad()
    if len(raw) > 20000:
        raise Bad()
    out = []
    ap = out.append
    total = 0
    for e in raw:
        if type(e) is not dict:
            raise Bad()
        op = e.get('op')
        if op == 'packet':
            if frozenset(e) != PACKET_KEYS:
                raise Bad()
            fid = e['flow']
            fi = fmap.get(fid) if type(fid) is str else None
            if fi is None:
                raise Bad()
            f = flows[fi]
            hdr = vhex(e['header'], f.H, f.H)
            pay = vhex(e['payload'], 0, 2048)
            total += f.H + len(pay)
            if total > MAX_PKT_BYTES:
                raise Bad()
            ap((4, fi, hdr, pay))
        elif op == 'put':
            if frozenset(e) != PUT_KEYS:
                raise Bad()
            fid = e['flow']
            fi = fmap.get(fid) if type(fid) is str else None
            if fi is None:
                raise Bad()
            nd = e['node']
            if type(nd) is not str or nd not in flows[fi].pathidx:
                raise Bad()
            ap((0, fi, nd))
        elif op == 'enable':
            if frozenset(e) != FLOW_KEYS:
                raise Bad()
            fid = e['flow']
            fi = fmap.get(fid) if type(fid) is str else None
            if fi is None:
                raise Bad()
            ap((1, fi))
        elif op == 'disable':
            if frozenset(e) != FLOW_KEYS:
                raise Bad()
            fid = e['flow']
            fi = fmap.get(fid) if type(fid) is str else None
            if fi is None:
                raise Bad()
            ap((2, fi))
        elif op == 'reset':
            if frozenset(e) != RESET_KEYS:
                raise Bad()
            ap((3,))
        else:
            raise Bad()
    return out


def do_replay(flows, fmap, caps, evs):
    tables = {}
    ncount = {}
    enabled = set()
    results = []
    ap = results.append
    tget = tables.get
    for ev in evs:
        op = ev[0]
        if op == 4:
            fi = ev[1]
            hdr = ev[2]
            pay = ev[3]
            f = flows[fi]
            N = f.N
            tpos = f.tpos
            qpos = f.qpos
            t0 = hdr[tpos]
            q = hdr[qpos]
            if fi not in enabled:
                mode = 'ip'
                reason = 'disabled'
            elif f.kget(hdr) != f.kexp:
                mode = 'ip'
                reason = 'mismatch'
            elif q > 7:
                mode = 'ip'
                reason = 'qos'
            else:
                mode = 'mpls'
                reason = 'compressed'
            L = t0 if t0 < N else N
            plen = len(pay)
            pay_hex = pay.hex() if plen else ''
            hi = int.from_bytes(hdr, 'big')
            if mode == 'mpls':
                if L:
                    dm = f.dmode
                    if dm == 0:
                        res_hex = ''
                    elif dm == 1:
                        res_hex = '%02x' % hdr[f.dpos0]
                    else:
                        res_hex = bytes(f.dget(hdr)).hex()
                    suffix = res_hex + pay_hex
                    qp = (q << 9) | 0x100
                    ls = f.labsh
                    wire = ['%08x' % (ls[j] + qp + t0 - j) + suffix for j in range(L)]
                    byte_hops = L * (4 + f.dcount + plen)
                else:
                    wire = []
                    byte_hops = 0
                if L == N:
                    xi = (hi & f.zmask & f.tclear) | ((t0 - N + 1) << f.tshift)
                    delivered = xi.to_bytes(f.H, 'big').hex() + pay_hex
                else:
                    delivered = None
            else:
                hx = hi.to_bytes(f.H, 'big').hex()
                p2 = f.tpos2
                pre = hx[:p2]
                post = hx[p2 + 2:] + pay_hex
                if L:
                    wire = [pre + '%02x' % (t0 - j) + post for j in range(L)]
                else:
                    wire = []
                byte_hops = L * (f.H + plen)
                if L == N:
                    delivered = pre + '%02x' % (t0 - N + 1) + post
                else:
                    delivered = None
            ap({'mode': mode, 'reason': reason, 'wire': wire,
                'delivered': delivered, 'byte_hops': byte_hops})
        elif op == 0:
            fi = ev[1]
            nd = ev[2]
            f = flows[fi]
            key = (nd, f.labels[f.pathidx[nd]])
            cur = tget(key)
            if cur == fi:
                st = 'ok'
            elif cur is not None and cur in enabled:
                st = 'busy'
            elif key not in tables and ncount.get(nd, 0) >= caps[nd]:
                st = 'full'
            else:
                if key not in tables:
                    ncount[nd] = ncount.get(nd, 0) + 1
                tables[key] = fi
                st = 'ok'
            ap({'status': st})
        elif op == 1:
            fi = ev[1]
            good = True
            for key in flows[fi].keys:
                if tget(key) != fi:
                    good = False
                    break
            if good:
                enabled.add(fi)
                ap(OK)
            else:
                ap({'status': 'unready'})
        elif op == 2:
            enabled.discard(ev[1])
            ap(OK)
        else:
            enabled.clear()
            ap(OK)
    active = sorted(flows[i].id for i in enabled)
    tabs = [{'node': nd, 'label': lb, 'flow': flows[fi].id}
            for (nd, lb), fi in tables.items()]
    tabs.sort(key=lambda d: (d['node'], d['label']))
    return {'results': results, 'active': active, 'tables': tabs}


def parse_plan(raw_warmup, raw_pinned, raw_offers, flows, fmap):
    warmup = vint(raw_warmup, 0, 1000000000)
    if type(raw_pinned) is not list:
        raise Bad()
    pinned = []
    pseen = set()
    for p in raw_pinned:
        if type(p) is not str:
            raise Bad()
        fi = fmap.get(p)
        if fi is None or fi in pseen:
            raise Bad()
        pseen.add(fi)
        pinned.append(fi)
    if type(raw_offers) is not dict:
        raise Bad()
    if len(raw_offers) != len(fmap) or set(raw_offers) != set(fmap):
        raise Bad()
    offers = [None] * len(flows)
    hdr_total = 0
    for fid, runs in raw_offers.items():
        if type(runs) is not list or len(runs) > 256:
            raise Bad()
        fi = fmap[fid]
        f = flows[fi]
        H = f.H
        lst = []
        cnt_sum = 0
        for r in runs:
            if type(r) is not dict or frozenset(r) != RUN_KEYS:
                raise Bad()
            hb = vhex(r['header'], H, H)
            cnt = vint(r['count'], 1, 1000000000)
            cnt_sum += cnt
            if cnt_sum > 1000000000:
                raise Bad()
            hdr_total += H
            if hdr_total > MAX_OFFER_HDR_BYTES:
                raise Bad()
            lst.append((hb, cnt))
        offers[fi] = lst
    return warmup, pinned, offers


def compute_benefits(flows, offers, warmup):
    bens = []
    for fi, f in enumerate(flows):
        per = f.save
        h = f.N - 1
        idx = 0
        tot = 0
        for hb, cnt in offers[fi]:
            if f.kget(hb) == f.kexp and hb[f.qpos] <= 7 and hb[f.tpos] > h:
                if idx >= warmup:
                    tot += cnt * per
                else:
                    e = idx + cnt
                    if e > warmup:
                        tot += (e - warmup) * per
            idx += cnt
        bens.append(tot)
    return bens


def _plan_search(b, usage, K, n):
    """Exact lexicographic (benefit, -count) maximisation over n candidates."""
    if n == 0:
        return 0, ()
    suf_total = [0] * (n + 1)
    acc = 0
    for i in range(n - 1, -1, -1):
        acc += b[i]
        suf_total[i] = acc
    pos = [[] for _ in range(K)]
    for i in range(n):
        for k in usage[i]:
            pos[k].append(i)
    plen = [len(p) for p in pos]
    pref = []
    suf = []
    start = []
    for k in range(K):
        p = pos[k]
        pr = [0] * (len(p) + 1)
        a = 0
        for j, i in enumerate(p):
            a += b[i]
            pr[j + 1] = a
        pref.append(pr)
        suf.append([pr[-1] - x for x in pr])
        start.append([bisect_left(p, i) for i in range(n + 1)])

    def bound(i, r, thresh):
        st = suf_total[i]
        if st <= thresh:
            return st
        best = st
        for k in range(K):
            j0 = start[k][i]
            m = plen[k] - j0
            rk = r[k]
            if rk < m:
                v = st - suf[k][j0] + pref[k][j0 + rk] - pref[k][j0]
                if v <= thresh:
                    return v
                if v < best:
                    best = v
        return best

    memo = {}
    sys.setrecursionlimit(10000)

    def rec(i, r):
        if i == n:
            return 0
        key = (i, r)
        got = memo.get(key)
        if got is not None:
            return got
        best = rec(i + 1, r)
        u = usage[i]
        fit = True
        for k in u:
            if r[k] == 0:
                fit = False
                break
        if fit:
            if len(u) == 1:
                k0 = u[0]
                r2 = r[:k0] + (r[k0] - 1,) + r[k0 + 1:]
            else:
                lst = list(r)
                for k in u:
                    lst[k] -= 1
                r2 = tuple(lst)
            bi = b[i]
            if bound(i + 1, r2, best - bi) > best - bi:
                val = bi + rec(i + 1, r2)
                if val > best:
                    best = val
        if len(memo) < MEMO_CAP:
            memo[key] = best
        return best

    total = rec(0, tuple(r0 for r0 in _R0[0]))
    sel = []
    r = tuple(_R0[0])
    for i in range(n):
        u = usage[i]
        fit = True
        for k in u:
            if r[k] == 0:
                fit = False
                break
        if not fit:
            continue
        if len(u) == 1:
            k0 = u[0]
            r2 = r[:k0] + (r[k0] - 1,) + r[k0 + 1:]
        else:
            lst = list(r)
            for k in u:
                lst[k] -= 1
            r2 = tuple(lst)
        if b[i] + rec(i + 1, r2) > rec(i + 1, r):
            sel.append(i)
            r = r2
    return total, tuple(sel)


_R0 = [()]


def do_plan(flows, fmap, caps, warmup, pinned, offers):
    bens = compute_benefits(flows, offers, warmup)
    nodes = sorted(caps)
    nidx = {nd: i for i, nd in enumerate(nodes)}
    nn = len(nodes)
    resid = [caps[nd] for nd in nodes]
    pset = set(pinned)
    for fi in pinned:
        for nd in flows[fi].path:
            j = nidx[nd]
            resid[j] -= 1
            if resid[j] < 0:
                return {'infeasible': True}
    knodes = [tuple(nidx[nd] for nd in flows[fi].path) for fi in range(len(flows))]
    cand = []
    for fi in range(len(flows)):
        if fi in pset or bens[fi] <= 0:
            continue
        ok = True
        for j in knodes[fi]:
            if resid[j] <= 0:
                ok = False
                break
        if ok:
            cand.append(fi)
    # node -> bitmask of candidates
    ncand = len(cand)
    cmask = [0] * nn
    ccount = [0] * nn
    cpos = {}
    for t, fi in enumerate(cand):
        cpos[fi] = t
        for j in knodes[fi]:
            cmask[j] |= (1 << t)
            ccount[j] += 1
    bind = [j for j in range(nn) if resid[j] < ccount[j]]
    # drop constraints implied by stronger ones
    bset = set(bind)
    for v in bind:
        if v not in bset:
            continue
        mv = cmask[v]
        rv = resid[v]
        for w in bind:
            if w == v or w not in bset:
                continue
            if (mv & cmask[w]) == mv and rv >= resid[w]:
                bset.discard(v)
                break
    bl = sorted(bset)
    bidx = {j: k for k, j in enumerate(bl)}
    forced = []
    dfs = []
    for fi in cand:
        used = tuple(bidx[j] for j in knodes[fi] if j in bidx)
        if used:
            dfs.append((fi, used))
        else:
            forced.append(fi)
    saved = 0
    for fi in pinned:
        saved += bens[fi]
    for fi in forced:
        saved += bens[fi]
    selected = [flows[fi].id for fi in pinned]
    selected.extend(flows[fi].id for fi in forced)
    n = len(dfs)
    if n:
        dfs.sort(key=lambda t: -bens[t[0]])
        order = [t[0] for t in dfs]
        usage = [t[1] for t in dfs]
        K = len(bl)
        mult = n + 1
        bb = [bens[fi] * mult - 1 for fi in order]
        r0 = []
        for k in range(K):
            c = 0
            for u in usage:
                if k in u:
                    c += 1
            rv = resid[bl[k]]
            r0.append(rv if rv < c else c)
        _R0[0] = tuple(r0)
        val, sel = _plan_search(bb, usage, K, n)
        for i in sel:
            fi = order[i]
            saved += bens[fi]
            selected.append(flows[fi].id)
    selected.sort()
    return {'selected': selected, 'saved': saved}


def handle(obj):
    if type(obj) is not dict:
        raise Bad()
    mode = obj.get('mode')
    if mode == 'replay':
        if frozenset(obj) != REPLAY_KEYS:
            raise Bad()
    elif mode == 'plan':
        if frozenset(obj) != PLAN_KEYS:
            raise Bad()
    else:
        raise Bad()
    caps = parse_caps(obj['capacities'])
    flows = parse_flows(obj['flows'], caps, mode == 'replay')
    fmap = {f.id: i for i, f in enumerate(flows)}
    if mode == 'replay':
        evs = parse_events(obj['events'], flows, fmap)
        return do_replay(flows, fmap, caps, evs)
    warmup, pinned, offers = parse_plan(obj['warmup'], obj['pinned'], obj['offers'],
                                        flows, fmap)
    return do_plan(flows, fmap, caps, warmup, pinned, offers)


def run():
    inp = sys.stdin.buffer
    out = sys.stdout.buffer
    write = out.write
    loads = json.loads
    dumps = json.dumps
    for raw in inp:
        if len(raw) > MAX_LINE or not raw.strip():
            write(ERR)
            continue
        try:
            obj = loads(raw, parse_float=_rej, parse_constant=_rej,
                        object_pairs_hook=_pairs)
            resp = handle(obj)
            write(dumps(resp, separators=(',', ':')).encode())
            write(b'\n')
        except Exception:
            write(ERR)
    out.flush()


if __name__ == '__main__':
    run()
